"""The engine's public service description served at `/`: status, features, HTTP endpoints and registered capabilities."""

from __future__ import annotations

from collections import Counter
from datetime import UTC, datetime
from pathlib import Path

from fastapi import FastAPI
from fastapi.routing import APIRoute
from pydantic import TypeAdapter

from mzizi_engine.runtime.contracts.base import Frozen
from mzizi_engine.runtime.operations import OperationRegistry

#: Generated by Dryv (pack `mzizi.system-catalog`) from `dryv/contracts/apps/engine`.
CATALOG_PATH = Path(__file__).resolve().parents[2] / "api" / "catalog" / "catalog.json"
STARTED_AT = datetime.now(UTC)


class ContractOperation(Frozen):
    name: str
    group: str
    feature: str
    method: str
    path: str
    role: str
    inputs: tuple[str, ...]
    output: str | None
    summary: str


class ContractCatalog(Frozen):
    generatedBy: str
    operations: tuple[ContractOperation, ...]


class EndpointReport(Frozen):
    method: str
    path: str
    handler: str
    contract: ContractOperation | None = None


class FeatureReport(Frozen):
    id: str
    name: str
    endpoints: int


class CapabilityReport(Frozen):
    name: str
    version: str
    package: str
    description: str
    cpu_bound: bool
    requires: tuple[str, ...]


class CapabilityGroup(Frozen):
    package: str
    capabilities: int


class SystemOverview(Frozen):
    service: str
    name: str
    status: str
    version: str
    time: datetime
    started_at: datetime
    uptime_seconds: int
    runtime: str
    store: str
    auth: str
    features: tuple[FeatureReport, ...]
    endpoints: tuple[EndpointReport, ...]
    capability_groups: tuple[CapabilityGroup, ...]
    capabilities: tuple[CapabilityReport, ...]
    contract_operations: int
    contract_generated_by: str | None


def load_catalog(path: Path = CATALOG_PATH) -> ContractCatalog | None:
    if not path.is_file():
        return None
    return TypeAdapter(ContractCatalog).validate_json(path.read_bytes())


def build_overview(
    app: FastAPI, registry: OperationRegistry, *, version: str, runtime: str, store: str, auth: str
) -> SystemOverview:
    catalog = load_catalog()
    declared = {(item.method, item.path): item for item in catalog.operations} if catalog else {}
    endpoints: list[EndpointReport] = []
    for route in app.routes:
        if not isinstance(route, APIRoute):
            continue
        for method in sorted((route.methods or set()) - {"HEAD", "OPTIONS"}):
            endpoints.append(
                EndpointReport(
                    method=method, path=route.path, handler=route.name, contract=declared.get((method, route.path))
                )
            )
    endpoints.sort(key=lambda item: (item.path, item.method))
    feature_counts = Counter(
        f"{item.contract.group}/{item.contract.feature}" if item.contract else "unlisted" for item in endpoints
    )
    capabilities = tuple(
        CapabilityReport(
            name=info.name,
            version=info.version,
            package=info.package,
            description=info.description,
            cpu_bound=info.cpu_bound,
            requires=tuple(sorted(item.value for item in registry.get(info.name).requires)),
        )
        for info in registry.describe()
    )
    packages = Counter(item.package for item in capabilities)
    now = datetime.now(UTC)
    return SystemOverview(
        service="mzizi-engine",
        name="Mzizi Africa research engine",
        status="ok",
        version=version,
        time=now,
        started_at=STARTED_AT,
        uptime_seconds=int((now - STARTED_AT).total_seconds()),
        runtime=runtime,
        store=store,
        auth=auth,
        features=tuple(
            FeatureReport(id=key, name=key.replace("/", " / ").replace("-", " ").title(), endpoints=count)
            for key, count in sorted(feature_counts.items())
        ),
        endpoints=tuple(endpoints),
        capability_groups=tuple(
            CapabilityGroup(package=key, capabilities=count) for key, count in sorted(packages.items())
        ),
        capabilities=capabilities,
        contract_operations=len(declared),
        contract_generated_by=catalog.generatedBy if catalog else None,
    )
